package com.crm.vendor.controller;
import com.crm.vendor.entity.Vendor; import com.crm.vendor.repository.VendorRepository; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/vendors") public class VendorController { private final VendorRepository repo; public VendorController(VendorRepository repo){this.repo=repo;} @GetMapping public List<Vendor> all(){return repo.findAll();} @GetMapping("/{id}") public ResponseEntity<Vendor> one(@PathVariable Long id){return repo.findById(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());} @PostMapping public ResponseEntity<Vendor> create(@RequestBody Vendor x){return ResponseEntity.status(HttpStatus.CREATED).body(repo.save(x));} @PutMapping("/{id}") public ResponseEntity<Vendor> update(@PathVariable Long id,@RequestBody Vendor x){return repo.findById(id).map(e->{e.setName(x.getName());e.setEmail(x.getEmail());e.setPhone(x.getPhone());e.setAddress(x.getAddress());e.setStatus(x.getStatus());return ResponseEntity.ok(repo.save(e));}).orElse(ResponseEntity.notFound().build());} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){if(!repo.existsById(id))return ResponseEntity.notFound().build();repo.deleteById(id);return ResponseEntity.noContent().build();} }